    /// Attach realm context defaults used for session metadata.
    ///
    /// Phase 4 R1: writes through the slot-shared inner runtime; both
    /// the RPC SessionRuntime and `MeerkatSessionRuntime` observe the
    /// same `Arc<RwLock<...>>` so a single write is enough.
    pub fn set_realm_context(
        &self,
        realm_id: Option<meerkat_core::connection::RealmId>,
        instance_id: Option<String>,
        backend: Option<String>,
    ) {
        self.inner.set_realm_context(realm_id, instance_id, backend);
    }

    pub fn set_skill_identity_roots(
        &self,
        context_root: Option<PathBuf>,
        user_root: Option<PathBuf>,
    ) {
        if let Ok(mut slot) = self.skill_identity_context_root.write() {
            *slot = context_root;
        }
        if let Ok(mut slot) = self.skill_identity_user_root.write() {
            *slot = user_root;
        }
    }

    pub fn skill_identity_roots(&self) -> (Option<PathBuf>, Option<PathBuf>) {
        let context_root = self
            .skill_identity_context_root
            .read()
            .map(|slot| slot.clone())
            .unwrap_or(None);
        let user_root = self
            .skill_identity_user_root
            .read()
            .map(|slot| slot.clone())
            .unwrap_or(None);
        (context_root, user_root)
    }

    /// Set the default mob tools factory for all agents built by this runtime.
    ///
    /// Writes through the shared slot to the `FactoryAgentBuilder` inside the
    /// session service — the builder that actually creates agents. The runtime's
    /// own `factory` clone is NOT used for session creation.
    pub fn set_mob_tools(&self, factory: Arc<dyn meerkat_core::service::MobToolsFactory>) {
        *self
            .builder_mob_tools_slot
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(factory);
    }

    /// Surface-agnostic core. Phase 4 R1 will collapse the duplicate
    /// per-field copies on `SessionRuntime` and route every accessor
    /// through `inner()`.
    pub fn inner(&self) -> &Arc<meerkat::session_runtime::MeerkatSessionRuntime> {
        &self.inner
    }

    /// Active realm id for this runtime, if configured.
    ///
    /// Phase 4 R1: routed through the slot-shared inner runtime so the
    /// RPC accessor and `MeerkatSessionRuntime::realm_id()` are
    /// guaranteed to observe the same value. Returns the owned variant
    /// because the slot read clones internally.
    pub fn realm_id(&self) -> Option<meerkat_core::connection::RealmId> {
        self.inner.realm_id()
    }

    /// Sessions whose durability gate currently demands a cold reload.
    ///
    /// Pass-through to the runtime adapter, which is private to this type.
    /// `None` means the registry was not readable; a health caller must report
    /// that as an unreadable dimension rather than publish a zero it did not
    /// observe.
    pub(crate) fn reload_required_session_count(&self) -> Option<usize> {
        self.runtime_adapter.reload_required_session_count()
    }

    /// Sessions still claiming a runtime loop whose task is gone.
    ///
    /// Pass-through to the runtime adapter, which is private to this type.
    /// `None` carries the same report-it-as-unreadable obligation as its
    /// sibling.
    pub(crate) fn dead_runtime_loop_session_count(&self) -> Option<usize> {
        self.runtime_adapter.dead_runtime_loop_session_count()
    }

    /// Sessions holding a staged run overdue to begin executing.
    ///
    /// Pass-through to the runtime adapter, which is private to this type.
    /// `None` carries the same report-it-as-unreadable obligation as its
    /// siblings, and additionally covers a past-bound window whose machine
    /// authority could not be read without blocking.
    pub(crate) fn overdue_run_start_session_count(&self) -> Option<usize> {
        self.runtime_adapter.overdue_run_start_session_count()
    }

    /// Sessions parked on queued work: input in the machine's queued phase
    /// past the notice bound, registration `Active`, no run in flight.
    ///
    /// Pass-through to the runtime adapter, which is private to this type.
    /// `None` carries the same report-it-as-unreadable obligation as its
    /// siblings.
    pub(crate) fn parked_queued_input_session_count(&self) -> Option<usize> {
        self.runtime_adapter.parked_queued_input_session_count()
    }

    /// Active instance id for this runtime, if configured.
    pub fn instance_id(&self) -> Option<String> {
        self.inner.instance_id()
    }

    /// Active backend label for this runtime, if configured.
    pub fn backend(&self) -> Option<String> {
        self.inner.backend()
    }

    /// Attach config runtime for generation stamping.
    pub fn set_config_runtime(&self, runtime: Arc<meerkat_core::ConfigRuntime>) {
        *self
            .config_runtime
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(runtime);
    }

    /// Shared config runtime used by config handlers.
    pub fn config_runtime(&self) -> Option<Arc<meerkat_core::ConfigRuntime>> {
        self.config_runtime
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
    }

    /// Attach the per-realm config-document source used by the auth-resolution
    /// read path AND the agent-BUILD path to compose the active realm's parent
    /// chain (inheritance).
    ///
    /// Also populates the builder-shared inheritance slot so
    /// `FactoryAgentBuilder::resolve_config` folds the active realm's parent
    /// chain (head ⊕ ancestors ⊕ `global` tail) into the effective config on
    /// every build. The head realm is this runtime's active realm, defaulting to
    /// the reserved `global` realm when none is configured — matching the
    /// connection resolver's head default.
    ///
    /// Writes never compose — `config get/set` stay on the raw `config_runtime`.
    pub fn set_realm_config_source(&self, source: Arc<dyn meerkat_core::RealmConfigSource>) {
        let head = self
            .realm_id()
            .unwrap_or_else(meerkat_core::connection::RealmId::global);
        *self
            .realm_config_source
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&source));
        *self
            .builder_realm_inheritance
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) =
            Some(meerkat::RealmInheritance::new(source, head));
    }

    /// Per-realm config-document source for inheritance composition, if attached.
    pub fn realm_config_source(&self) -> Option<Arc<dyn meerkat_core::RealmConfigSource>> {
        self.realm_config_source
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
    }

    async fn pending_live_first_turn_is_still_deferred(
        service: &PersistentSessionService<FactoryAgentBuilder>,
        session_id: &SessionId,
    ) -> Result<bool, SessionError> {
        meerkat::session_runtime::staged_promotion::pending_live_first_turn_is_still_deferred(
            service, session_id,
        )
        .await
    }

    #[cfg(test)]
    async fn should_restore_pending_after_start_turn(
        service: &PersistentSessionService<FactoryAgentBuilder>,
        session_id: &SessionId,
        result: &Result<RunResult, SessionError>,
    ) -> Result<bool, SessionError> {
        if Self::is_pre_run_start_turn_failure(result) {
            return Ok(true);
        }
        if result.is_err() {
            Self::pending_live_first_turn_is_still_deferred(service, session_id).await
        } else {
            Ok(false)
        }
    }

    async fn should_restore_pending_after_apply_runtime_turn(
        service: &PersistentSessionService<FactoryAgentBuilder>,
        session_id: &SessionId,
        result: &Result<CoreApplyOutput, SessionError>,
    ) -> Result<bool, SessionError> {
        if Self::is_pre_run_apply_runtime_turn_failure(result) {
            return Ok(true);
        }
        if result.is_err() {
            Self::pending_live_first_turn_is_still_deferred(service, session_id).await
        } else {
            Ok(false)
        }
    }

    async fn reserve_active_turn(
        &self,
        session_id: &SessionId,
    ) -> Result<RuntimePreAdmission, RpcError> {
        if let Some(admission) = self.take_staged_capacity_admission(session_id) {
            return Ok(RuntimePreAdmission::staged(
                session_id.clone(),
                Arc::clone(&self.staged_capacity_admissions),
                admission,
            ));
        }
        self.service
            .reserve_runtime_turn_admission(session_id)
            .await
            .map(RuntimePreAdmission::fresh)
            .map_err(session_error_to_rpc)
    }

    async fn reserve_or_join_active_turn(
        &self,
        session_id: &SessionId,
    ) -> Result<RuntimePreAdmission, RpcError> {
        if let Some(admission) = self.take_staged_capacity_admission(session_id) {
            return Ok(RuntimePreAdmission::staged(
                session_id.clone(),
                Arc::clone(&self.staged_capacity_admissions),
                admission,
            ));
        }
        self.service
            .reserve_runtime_turn_admission(session_id)
            .await
            .map(RuntimePreAdmission::fresh)
            .map_err(session_error_to_rpc)
    }

    fn insert_staged_capacity_admission(
        &self,
        session_id: SessionId,
        admission: ActiveCapacityGuard,
    ) -> Result<(), RpcError> {
        admission_insert_staged_capacity(&self.staged_capacity_admissions, session_id, admission)
            .map_err(|StagedCapacityCollision { session_id }| RpcError {
                code: error::SESSION_BUSY,
                message: format!("session {session_id} already has staged capacity"),
                data: None,
            })
    }

    fn take_staged_capacity_admission(
        &self,
        session_id: &SessionId,
    ) -> Option<ActiveCapacityGuard> {
        admission_take_staged_capacity(&self.staged_capacity_admissions, session_id)
    }

    fn has_staged_capacity_admission(&self, session_id: &SessionId) -> bool {
        admission_has_staged_capacity(&self.staged_capacity_admissions, session_id)
    }

    fn discard_staged_capacity_admission(&self, session_id: &SessionId) {
        admission_discard_staged_capacity(&self.staged_capacity_admissions, session_id);
    }

    pub(crate) fn take_runtime_pre_admission(
        &self,
        session_id: &SessionId,
        input_ids: &[InputId],
    ) -> Option<RuntimePreAdmission> {
        if input_ids.is_empty() {
            return None;
        }
        let mut pre_admissions = self
            .runtime_pre_admissions
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let entries = pre_admissions.get_mut(session_id)?;
        let index = entries
            .iter()
            .position(|entry| input_ids.contains(&entry.input_id))?;
        let entry = entries.remove(index);
        if entries.is_empty() {
            pre_admissions.remove(session_id);
        }
        Some(entry.admission)
    }

    fn insert_runtime_pre_admission(
        &self,
        session_id: SessionId,
        input_id: InputId,
        admission: impl Into<RuntimePreAdmission>,
    ) -> Result<(), RpcError> {
        let mut pre_admissions = self
            .runtime_pre_admissions
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let entries = pre_admissions.entry(session_id.clone()).or_default();
        if entries.iter().any(|entry| entry.input_id == input_id) {
            return Err(RpcError {
                code: error::SESSION_BUSY,
                message: format!("session {session_id} already has queued runtime work"),
                data: None,
            });
        }
        entries.push(RuntimePreAdmissionEntry {
            input_id,
            admission: admission.into(),
        });
        Ok(())
    }

    fn restore_or_release_runtime_pre_admission(&self, session_id: &SessionId, input_id: &InputId) {
        let Some(admission) =
            self.take_runtime_pre_admission(session_id, std::slice::from_ref(input_id))
        else {
            return;
        };
        drop(admission);
    }

    fn register_runtime_pre_admission(
        self: &Arc<Self>,
        session_id: SessionId,
        input_id: InputId,
        admission: impl Into<RuntimePreAdmission>,
    ) -> Result<RuntimePreAdmissionRegistration, RpcError> {
        self.insert_runtime_pre_admission(session_id.clone(), input_id.clone(), admission)?;
        Ok(RuntimePreAdmissionRegistration::new(
            Arc::clone(self) as Arc<dyn RuntimePreAdmissionRestore>,
            session_id,
            input_id,
        ))
    }

    fn runtime_registration_lock(
        self: &Arc<Self>,
        session_id: &SessionId,
    ) -> RuntimeRegistrationLockLease {
        let lock = {
            let mut locks = self
                .runtime_registration_locks
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if let Some(lock) = locks.get(session_id).and_then(Weak::upgrade) {
                lock
            } else {
                let lock = Arc::new(Mutex::new(()));
                locks.insert(session_id.clone(), Arc::downgrade(&lock));
                lock
            }
        };
        RuntimeRegistrationLockLease {
            locks: Arc::clone(&self.runtime_registration_locks),
            session_id: session_id.clone(),
            lock,
        }
    }

    async fn unregister_new_runtime_registration_if_idle(
        self: &Arc<Self>,
        adapter: &Arc<MeerkatMachine>,
        session_id: &SessionId,
        runtime_was_registered: bool,
        staged_session_existed: bool,
        protect_active_admission: bool,
    ) -> Result<(), RpcError> {
        if runtime_was_registered || staged_session_existed {
            return Ok(());
        }
        if !adapter.contains_session(session_id).await {
            return Ok(());
        }
        if self.staged_sessions.contains(session_id).await {
            return Ok(());
        }
        let _ = protect_active_admission;
        if !adapter
            .list_active_inputs(session_id)
            .await
            .map_err(runtime_driver_error_to_rpc)?
            .is_empty()
        {
            return Ok(());
        }
        match self.service.has_live_session(session_id).await {
            Ok(true) => return Ok(()),
            Ok(false) => {}
            Err(error) => {
                return Err(RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!(
                        "failed to inspect live-session ownership while compensating new RPC runtime for session {session_id}: {error}"
                    ),
                    data: None,
                });
            }
        }
        adapter
            .unregister_session(session_id)
            .await
            .map_err(runtime_driver_error_to_rpc)
    }

    async fn unregister_new_runtime_registration_after_rpc_error(
        self: &Arc<Self>,
        adapter: &Arc<MeerkatMachine>,
        session_id: &SessionId,
        runtime_was_registered: bool,
        staged_session_existed: bool,
        protect_active_admission: bool,
        primary: RpcError,
    ) -> RpcError {
        match self
            .unregister_new_runtime_registration_if_idle(
                adapter,
                session_id,
                runtime_was_registered,
                staged_session_existed,
                protect_active_admission,
            )
            .await
        {
            Ok(()) => primary,
            Err(cleanup) => RpcError {
                code: primary.code,
                message: format!(
                    "{}; additionally failed to unregister newly prepared RPC runtime for session {session_id}: {}",
                    primary.message, cleanup.message
                ),
                data: primary.data,
            },
        }
    }

    async fn cleanup_runtime_after_completion_outcome(
        self: &Arc<Self>,
        session_id: &SessionId,
        cleanup_observation: meerkat_runtime::CompletionCleanupObservation,
    ) -> Result<Option<bool>, RuntimeCompletionCleanupFailure> {
        // Serialize the final observation/unregister decision with RPC runtime
        // materialization. Otherwise a replacement runtime could be inserted
        // after cleanup authority is resolved and then be mistaken for the
        // registration owned by this completion.
        let runtime_registration_lock = self.runtime_registration_lock(session_id);
        let _runtime_registration_guard = runtime_registration_lock.mutex().lock().await;
        let archived_now = match self.authoritative_session_archived(session_id).await {
            Ok(archived_now) => archived_now,
            Err(error) => {
                return Err(RuntimeCompletionCleanupFailure {
                    releases_pre_admission: false,
                    error: meerkat_runtime::CompletionWaitError::AuthorityUnavailable(format!(
                        "runtime completion archive authority unavailable for session {session_id}: {error:?}"
                    )),
                });
            }
        };
        let live_session = if archived_now {
            meerkat_runtime::meerkat_machine::dsl::RuntimeCompletionLiveSessionObservation::NotObserved
        } else {
            match self.service.has_live_session(session_id).await {
                Ok(true) => {
                    meerkat_runtime::meerkat_machine::dsl::RuntimeCompletionLiveSessionObservation::Present
                }
                Ok(false) => {
                    meerkat_runtime::meerkat_machine::dsl::RuntimeCompletionLiveSessionObservation::Absent
                }
                Err(error) => {
                    return Err(RuntimeCompletionCleanupFailure {
                        releases_pre_admission: false,
                        error: meerkat_runtime::CompletionWaitError::AuthorityUnavailable(
                            format!(
                                "runtime completion live-session authority unavailable for session {session_id}: {error}"
                            ),
                        ),
                    });
                }
            }
        };
        let runtime_termination_cleanup = cleanup_observation
            .proves_runtime_termination_for(session_id)
            && matches!(
                live_session,
                meerkat_runtime::meerkat_machine::dsl::RuntimeCompletionLiveSessionObservation::Absent
            );
        let runtime_termination_proof = cleanup_observation.clone();
        let cleanup_authority = match self
            .runtime_adapter
            .resolve_runtime_completion_cleanup(
                session_id,
                cleanup_observation,
                archived_now,
                live_session,
            )
            .await
        {
            Ok(authority) => authority,
            Err(error) => {
                if archived_now && !self.runtime_adapter.contains_session(session_id).await {
                    // Benign post-teardown arrival: the session was archived
                    // (its unregister drain already resolved every completion
                    // waiter with the committed/terminal outcome) and its
                    // runtime entry is gone, so cleanup-authority resolution has
                    // nothing left to act on. This is the expected race when a
                    // completion waiter resolves after archive, not a fault.
                    tracing::debug!(
                        %session_id,
                        error = ?error,
                        "runtime completion cleanup observed a post-archive teardown (benign)"
                    );
                    return Ok(Some(true));
                }
                if runtime_termination_cleanup
                    && !self.runtime_adapter.contains_session(session_id).await
                {
                    // The machine-owned unregister coordinator can remove the
                    // entry before completion waiters are delivered, after
                    // the executor's external-only cleanup discarded the live
                    // session. The
                    // runtime-minted, session-bound RuntimeTerminated
                    // observation plus independently observed absent live
                    // session is the narrow proof that lets the relay finish
                    // the remaining surface anchors without weakening
                    // ordinary cleanup.
                    return match self
                        .archive_runtime_cleanup()
                        .run_after_runtime_termination(session_id, &runtime_termination_proof)
                        .await
                    {
                        Ok(()) => Ok(Some(true)),
                        Err(cleanup_error) => Err(RuntimeCompletionCleanupFailure {
                            // RuntimeTerminated cleanup authority always
                            // releases this input's pre-admission. Retaining it
                            // after the runtime and live session are proven
                            // terminal would leak capacity while offering no
                            // retry authority. Required cleanup failure still
                            // withholds the public completion outcome.
                            releases_pre_admission: true,
                            error: meerkat_runtime::CompletionWaitError::AuthorityUnavailable(
                                format!(
                                    "runtime completion cleanup failed for session {session_id}: runtime cleanup failed: {cleanup_error}"
                                ),
                            ),
                        }),
                    };
                }
                return Err(RuntimeCompletionCleanupFailure {
                    releases_pre_admission: false,
                    error: meerkat_runtime::CompletionWaitError::AuthorityUnavailable(format!(
                        "generated runtime completion cleanup authority unavailable for session {session_id}: {error}"
                    )),
                });
            }
        };
        if cleanup_authority.requires_runtime_cleanup() {
            let discard_error = match self.service.discard_live_session(session_id).await {
                Ok(()) | Err(SessionError::NotFound { .. }) => None,
                Err(error) => Some(error),
            };
            let runtime_cleanup_error = if runtime_termination_cleanup
                && !self.runtime_adapter.contains_session(session_id).await
            {
                self.archive_runtime_cleanup()
                    .run_after_runtime_termination(session_id, &runtime_termination_proof)
                    .await
                    .err()
            } else {
                self.archive_runtime_cleanup().run(session_id).await.err()
            };
            if discard_error.is_some() || runtime_cleanup_error.is_some() {
                let mut causes = Vec::new();
                if let Some(error) = discard_error {
                    causes.push(format!("live-session discard failed: {error}"));
                }
                if let Some(error) = runtime_cleanup_error {
                    causes.push(format!("runtime cleanup failed: {error}"));
                }
                return Err(RuntimeCompletionCleanupFailure {
                    releases_pre_admission: cleanup_authority.releases_pre_admission(),
                    error: meerkat_runtime::CompletionWaitError::AuthorityUnavailable(format!(
                        "runtime completion cleanup failed for session {session_id}: {}",
                        causes.join("; ")
                    )),
                });
            }
        }
        Ok(Some(cleanup_authority.releases_pre_admission()))
    }

    async fn release_runtime_pre_admission_after_wait_failure_authority(
        &self,
        session_id: &SessionId,
        input_id: &InputId,
        error: &meerkat_runtime::CompletionWaitError,
    ) {
        match self
            .runtime_adapter
            .resolve_runtime_completion_wait_failure(session_id, error)
            .await
        {
            Ok(authority) => {
                if authority.releases_pre_admission() {
                    self.restore_or_release_runtime_pre_admission(session_id, input_id);
                }
            }
            Err(authority_error) => {
                tracing::warn!(
                    %session_id,
                    %input_id,
                    error = %error,
                    authority_error = ?authority_error,
                    "RPC runtime pre-admission retained because generated wait-failure authority was unavailable"
                );
            }
        }
    }

    async fn runtime_completion_wait_error_to_rpc_error(
        &self,
        error: meerkat_runtime::completion::CompletionWaitError,
        session_id: &SessionId,
    ) -> RpcError {
        match self
            .runtime_adapter
            .resolve_runtime_completion_wait_failure(session_id, &error)
            .await
        {
            Ok(authority) => RpcError {
                code: runtime_completion_wait_failure_rpc_code(authority.public_error_class),
                message: format!("runtime completion waiter failed: {error}"),
                data: Some(serde_json::json!({
                    "session_id": session_id.to_string(),
                    "reason": runtime_completion_wait_failure_rpc_reason(authority.public_reason),
                    "public_error_class": format!("{:?}", authority.public_error_class),
                    "resumable": authority.resumable,
                })),
            },
            Err(authority_error) => RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "runtime completion waiter failed without generated failure authority: {error}"
                ),
                data: Some(serde_json::json!({
                    "session_id": session_id.to_string(),
                    "authority_error": authority_error.to_string(),
                })),
            },
        }
    }

    fn spawn_runtime_pre_admission_cleanup(
        self: &Arc<Self>,
        session_id: SessionId,
        input_id: InputId,
        handle: meerkat_runtime::CompletionHandle,
    ) {
        drop(self.spawn_runtime_pre_admission_cleanup_with_outcome(session_id, input_id, handle));
    }

    fn spawn_runtime_pre_admission_cleanup_with_outcome(
        self: &Arc<Self>,
        session_id: SessionId,
        input_id: InputId,
        handle: meerkat_runtime::CompletionHandle,
    ) -> tokio::sync::oneshot::Receiver<
        Result<meerkat_runtime::CompletionOutcome, meerkat_runtime::CompletionWaitError>,
    > {
        let runtime = Arc::clone(self);
        let (outcome_tx, outcome_rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            let completion = handle.try_wait_with_cleanup_observation().await;
            match completion {
                Ok((outcome, cleanup_observation)) => {
                    let cleanup_result = runtime
                        .cleanup_runtime_after_completion_outcome(&session_id, cleanup_observation)
                        .await;
                    match gate_runtime_completion_outcome(outcome, cleanup_result) {
                        Ok((outcome, cleanup_authority)) => {
                            if cleanup_authority == Some(true) {
                                runtime.restore_or_release_runtime_pre_admission(
                                    &session_id,
                                    &input_id,
                                );
                            }
                            let _ = outcome_tx.send(Ok(outcome));
                        }
                        Err(cleanup_failure) => {
                            if cleanup_failure.releases_pre_admission {
                                runtime.restore_or_release_runtime_pre_admission(
                                    &session_id,
                                    &input_id,
                                );
                            }
                            tracing::warn!(
                                %session_id,
                                %input_id,
                                error = %cleanup_failure.error,
                                "runtime completion outcome withheld because required cleanup failed"
                            );
                            let _ = outcome_tx.send(Err(cleanup_failure.error));
                        }
                    }
                }
                Err(error) => {
                    runtime
                        .release_runtime_pre_admission_after_wait_failure_authority(
                            &session_id,
                            &input_id,
                            &error,
                        )
                        .await;
                    tracing::warn!(
                        %session_id,
                        %input_id,
                        error = %error,
                        "runtime completion waiter failed before RPC completion cleanup"
                    );
                    let _ = outcome_tx.send(Err(error));
                }
            }
        });
        outcome_rx
    }

    fn spawn_runtime_pre_admission_idle_cleanup(
        self: &Arc<Self>,
        session_id: SessionId,
        input_id: InputId,
    ) {
        let runtime = Arc::clone(self);
        tokio::spawn(async move {
            loop {
                let runtime_running = runtime
                    .runtime_adapter
                    .runtime_state(&session_id)
                    .await
                    .is_ok_and(|state| matches!(state, meerkat_runtime::RuntimeState::Running));
                let input_still_active = runtime
                    .runtime_adapter
                    .list_active_inputs(&session_id)
                    .await
                    .is_ok_and(|inputs| inputs.contains(&input_id));
                if !runtime_running || !input_still_active {
                    runtime.restore_or_release_runtime_pre_admission(&session_id, &input_id);
                    break;
                }
                tokio::time::sleep(tokio::time::Duration::from_millis(10)).await;
            }
        });
    }

