    #[cfg(test)]
    async fn wait_pending_promotion_pre_turn_hook(
        hook_slot: &Arc<StdMutex<Option<Arc<PendingPromotionPreTurnHook>>>>,
    ) {
        let hook = hook_slot
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        let Some(hook) = hook else {
            return;
        };
        let released = hook.release.notified();
        hook.reached_flag
            .store(true, std::sync::atomic::Ordering::SeqCst);
        hook.reached.notify_waiters();
        released.await;
    }

    #[cfg(test)]
    pub(crate) async fn wait_runtime_routed_pre_promotion_hook(&self, session_id: &SessionId) {
        if self
            .staged_sessions
            .info(session_id)
            .await
            .ok()
            .flatten()
            .is_none_or(|info| info.is_promoting)
        {
            return;
        }
        if self.has_staged_capacity_admission(session_id) {
            return;
        }
        Self::wait_pending_promotion_pre_turn_hook(&self.runtime_routed_pre_promotion_hook).await;
    }

    #[cfg(test)]
    fn spawn_pending_create_and_start_turn_with_admission_guard(
        &self,
        session_id: SessionId,
        create_req: CreateSessionRequest,
        start_req: StartTurnRequest,
        promotion_cleanup: PendingPromotionCleanup,
        generated_machine_archived_resume_admission: GeneratedMachineArchivedResumeAdmission,
    ) -> ServiceStartTurnResultReceiver {
        let pre_turn_hook = self.pending_promotion_pre_turn_hook_callback();
        let expected_session_id = session_id.clone();
        let runtime_actor_witness_slots = Arc::clone(&self.runtime_actor_witness_slots);
        let actor_witness_capture: meerkat::session_runtime::staged_promotion::ActorWitnessSlotCaptureFn =
            Arc::new(move |materialized_session_id, actor_witness_slot| {
                debug_assert_eq!(materialized_session_id, expected_session_id);
                runtime_actor_witness_slots
                    .write()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .insert(materialized_session_id, actor_witness_slot);
            });
        meerkat::session_runtime::staged_promotion::spawn_pending_create_and_start_turn_with_admission_guard(
            Arc::clone(&self.service),
            Arc::clone(&self.staged_sessions),
            Arc::clone(&self.runtime_adapter),
            actor_witness_capture,
            pre_turn_hook,
            session_id,
            create_req,
            start_req,
            promotion_cleanup,
            generated_machine_archived_resume_admission,
        )
    }

