    /// Phase 4 R1: build a [`LiveOrchestrator`] borrowing this
    /// runtime's resolved state. Surface-private dependencies
    /// (callback dispatcher, archive cleanup) are
    /// passed in by the caller so the orchestrator stays free of
    /// RPC-private types.
    fn live_orchestrator<'a>(
        &'a self,
        snapshot: &'a RealmContextSnapshot,
        archive_runtime_cleanup: meerkat::session_runtime::runtime_state::ArchiveRuntimeCleanup,
    ) -> meerkat::session_runtime::live_orchestration::LiveOrchestrator<'a> {
        let agent_llm_client_decorator = self
            .agent_llm_client_decorator
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        let runtime_actor_witness_slots = Arc::clone(&self.runtime_actor_witness_slots);
        let actor_witness_capture: meerkat::session_runtime::staged_promotion::ActorWitnessSlotCaptureFn =
            Arc::new(move |materialized_session_id, actor_witness_slot| {
                runtime_actor_witness_slots
                    .write()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .insert(materialized_session_id, actor_witness_slot);
            });
        meerkat::session_runtime::live_orchestration::LiveOrchestrator {
            service: &self.service,
            staged_sessions: &self.staged_sessions,
            staged_capacity_admissions: &self.staged_capacity_admissions,
            runtime_adapter: &self.runtime_adapter,
            host: self.live_adapter_host(),
            config_runtime: self.config_runtime(),
            default_llm_client: self.default_llm_client(),
            agent_llm_client_decorator,
            external_tools: self.recovery_external_tools(),
            archive_runtime_cleanup,
            realm_id: snapshot.realm_id.as_ref(),
            instance_id: snapshot.instance_id.as_deref(),
            backend: snapshot.backend.as_deref(),
            // Only the open pipeline needs the session-owned ingress hook;
            // `open_live_channel` installs `RpcLiveIngressReconciler` on
            // its per-call orchestrator.
            ingress_reconciler: None,
            actor_witness_capture,
        }
    }

    fn recovery_overrides_from_turn(
        &self,
        overrides: Option<&crate::handlers::turn::TurnOverrides>,
        keep_alive: bool,
    ) -> Result<SurfaceSessionRecoveryOverrides, RpcError> {
        let output_schema = match overrides.and_then(|ov| ov.output_schema.clone()) {
            Some(value) => Some(meerkat_core::OutputSchema::from_json_value(value).map_err(
                |e| RpcError {
                    code: error::INVALID_PARAMS,
                    message: format!("Invalid output_schema override: {e}"),
                    data: None,
                },
            )?),
            None => None,
        };

        Ok(SurfaceSessionRecoveryOverrides {
            model: overrides.and_then(|ov| ov.model.clone()),
            provider: overrides
                .and_then(|ov| ov.provider.as_ref())
                .map(|provider| parse_provider_override(provider))
                .transpose()
                .map_err(|message| RpcError {
                    code: error::INVALID_PARAMS,
                    message,
                    data: None,
                })?,
            self_hosted_server_id: overrides.and_then(|ov| ov.self_hosted_server_id.clone()),
            provider_params: overrides.and_then(|ov| ov.provider_params.clone()),
            auth_binding: overrides.and_then(|ov| ov.auth_binding.clone()),
            max_tokens: overrides.and_then(|ov| ov.max_tokens),
            output_schema,
            structured_output_retries: overrides.and_then(|ov| ov.structured_output_retries),
            keep_alive: Some(keep_alive),
            ..Default::default()
        })
    }

    fn recovery_external_tools(&self) -> Option<Arc<dyn meerkat_core::AgentToolDispatcher>> {
        self.callback_tool_dispatcher(vec![])
            .map(|dispatcher| Arc::new(dispatcher) as Arc<dyn meerkat_core::AgentToolDispatcher>)
    }

    /// Translate the surface-agnostic [`meerkat::session_runtime::errors::RecoveryError`]
    /// onto an RPC wire error. Stays in `meerkat-rpc` because the
    /// destination type (`RpcError`) is RPC-private.
    fn recovery_error_to_rpc(error: meerkat::session_runtime::errors::RecoveryError) -> RpcError {
        use meerkat::session_runtime::errors::RecoveryError;
        match error {
            RecoveryError::Recovery(SurfaceSessionRecoveryError::InvalidOverride(message)) => {
                RpcError {
                    code: error::INVALID_PARAMS,
                    message,
                    data: None,
                }
            }
            RecoveryError::Recovery(other) => RpcError {
                code: error::INTERNAL_ERROR,
                message: other.to_string(),
                data: None,
            },
            RecoveryError::BindingPreparation { .. } => RpcError {
                code: error::INTERNAL_ERROR,
                message: error.to_string(),
                data: None,
            },
            RecoveryError::Session(session_error) => session_error_to_rpc(session_error),
        }
    }

    /// Snapshot of the slot-shared realm/instance/backend triple. The
    /// `RecoveryContext` borrows from this scratch struct so the slot
    /// reads happen once at the call site without the borrow checker
    /// rejecting temporary owned values.
    fn realm_context_snapshot(&self) -> RealmContextSnapshot {
        RealmContextSnapshot {
            realm_id: self.inner.realm_id(),
            instance_id: self.inner.instance_id(),
            backend: self.inner.backend(),
        }
    }

    /// Build a [`RecoveryContext`] borrowing this runtime's resolved
    /// state. Used by the `recovered_create_request*` shims and any
    /// surface that wants direct access to the surface-agnostic
    /// recovery flow without an RPC translation.
    ///
    /// Takes a `&RealmContextSnapshot` because the surface-agnostic
    /// `RecoveryContext` borrows the realm triple; callers stash the
    /// snapshot in a local binding that outlives the context.
    fn recovery_context<'a>(
        &'a self,
        snapshot: &'a RealmContextSnapshot,
    ) -> meerkat::session_runtime::recovery::RecoveryContext<'a> {
        let agent_llm_client_decorator = {
            self.agent_llm_client_decorator
                .read()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone()
        };
        meerkat::session_runtime::recovery::RecoveryContext {
            service: &self.service,
            runtime_adapter: &self.runtime_adapter,
            realm_id: snapshot.realm_id.as_ref(),
            instance_id: snapshot.instance_id.as_deref(),
            backend: snapshot.backend.as_deref(),
            default_llm_client: self.default_llm_client(),
            agent_llm_client_decorator,
            external_tools: self.recovery_external_tools(),
            config_runtime: self.config_runtime(),
        }
    }

    async fn recovered_create_request(
        &self,
        session_id: &SessionId,
        session: Session,
        overrides: SurfaceSessionRecoveryOverrides,
    ) -> Result<RecoveredCreateRequest, RpcError> {
        let snapshot = self.realm_context_snapshot();
        self.recovery_context(&snapshot)
            .recovered_create_request(session_id, session, overrides)
            .await
            .map_err(Self::recovery_error_to_rpc)
    }

    async fn recovered_create_request_with_runtime_binding_mode(
        &self,
        session_id: &SessionId,
        session: Session,
        overrides: SurfaceSessionRecoveryOverrides,
        binding_mode: RecoveryRuntimeBindingMode,
    ) -> Result<RecoveredCreateRequest, RpcError> {
        let snapshot = self.realm_context_snapshot();
        self.recovery_context(&snapshot)
            .recovered_create_request_with_runtime_binding_mode(
                session_id,
                session,
                overrides,
                binding_mode,
            )
            .await
            .map_err(Self::recovery_error_to_rpc)
    }

    pub fn schedule_service(&self) -> ScheduleService {
        self.schedule_service.clone()
    }

    pub fn detached_job_service(&self) -> meerkat::DetachedJobService {
        meerkat::DetachedJobService::new(self.job_store.clone())
    }

    /// Record an explicit durable session wait for a detached job.
    ///
    /// This returns after MeerkatMachine accepts the wait binding; it never
    /// keeps a provider turn open while the job executes.
    pub async fn await_job(
        self: &Arc<Self>,
        session_id: &SessionId,
        reference: &meerkat::JobReference,
    ) -> Result<meerkat::JobAwaitReceipt, RpcError> {
        self.ensure_runtime_executor(session_id).await?;
        let realm_id = self.realm_id().ok_or_else(|| RpcError {
            code: error::INTERNAL_ERROR,
            message: "await_job requires an active realm".to_string(),
            data: None,
        })?;
        let operations = self
            .runtime_adapter
            .ops_lifecycle_registry(session_id)
            .await
            .ok_or_else(|| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "await_job could not resolve runtime operation authority for {session_id}"
                ),
                data: None,
            })?;
        meerkat::JobAwaitCoordinator::new(
            realm_id.to_string(),
            self.detached_job_service(),
            operations,
        )
        .await_job(session_id, reference)
        .await
        .map_err(|error| RpcError {
            code: error::INVALID_REQUEST,
            message: error.to_string(),
            data: None,
        })
    }

    pub async fn detached_job_await_activity(
        &self,
        session_id: &SessionId,
    ) -> Result<Option<meerkat::JobAwaitActivity>, RpcError> {
        let Some(realm_id) = self.realm_id() else {
            return Ok(None);
        };
        let Some(operations) = self
            .runtime_adapter
            .ops_lifecycle_registry(session_id)
            .await
        else {
            return Ok(None);
        };
        meerkat::JobAwaitCoordinator::new(
            realm_id.to_string(),
            self.detached_job_service(),
            operations,
        )
        .activity_for_session(session_id)
        .map_err(|error| RpcError {
            code: error::INTERNAL_ERROR,
            message: format!(
                "failed to project detached job wait activity for {session_id}: {error}"
            ),
            data: None,
        })
    }

    pub async fn detached_job_awaiting_member_count(&self) -> Result<u64, RpcError> {
        let sessions = self.list_sessions(SessionQuery::default()).await?;
        let unique_sessions = sessions
            .into_iter()
            .map(|session| (session.session_id.to_string(), session.session_id))
            .collect::<BTreeMap<_, _>>();
        let mut awaiting = 0_u64;
        for session_id in unique_sessions.into_values() {
            if self
                .detached_job_await_activity(&session_id)
                .await?
                .is_some()
            {
                awaiting = awaiting.saturating_add(1);
            }
        }
        Ok(awaiting)
    }

    pub(crate) async fn monitor_job_manager_for_session(
        self: &Arc<Self>,
        session_id: &SessionId,
    ) -> Result<Arc<meerkat_tools::builtin::shell::JobManager>, RpcError> {
        if let Some(manager) = self.monitor_job_managers.lock().await.get(session_id) {
            return Ok(Arc::clone(manager));
        }
        if !self.factory.enable_shell {
            return Err(RpcError {
                code: error::INVALID_REQUEST,
                message: "monitors/start requires shell capability".to_string(),
                data: None,
            });
        }
        let realm_id = self.realm_id().ok_or_else(|| RpcError {
            code: error::INTERNAL_ERROR,
            message: "monitors/start requires an active realm".to_string(),
            data: None,
        })?;
        let project_root = self
            .factory
            .project_root
            .clone()
            .or_else(|| self.factory.context_root.clone())
            .ok_or_else(|| RpcError {
                code: error::INVALID_REQUEST,
                message: "monitors/start requires an explicit project or context root".to_string(),
                data: None,
            })?;
        self.ensure_runtime_executor(session_id).await?;
        let ops_registry = self
            .runtime_adapter
            .ops_lifecycle_registry(session_id)
            .await
            .ok_or_else(|| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "monitors/start could not resolve runtime operation authority for {session_id}"
                ),
                data: None,
            })?;
        let projector: Arc<dyn meerkat_tools::builtin::shell::ShellJobDeliveryProjector> =
            Arc::new(meerkat::JobOutboxProjector::new_for_realm(
                self.job_store.clone(),
                self.runtime_delivery_inbox.clone(),
                realm_id.to_string(),
            ));
        let durable = meerkat_tools::builtin::shell::DurableShellJobRuntime::new(
            realm_id.to_string(),
            session_id.clone(),
            self.job_store.clone(),
            self.blob_store(),
            projector,
        )
        .map_err(|error| RpcError {
            code: error::INVALID_REQUEST,
            message: error.to_string(),
            data: None,
        })?;
        // Project the effective realm config's `[shell]` vocabulary into the
        // monitor job manager, same seam as the factory-composed shell tool.
        let effective_config = self.effective_config().await?;
        let manager = Arc::new(
            meerkat_tools::builtin::shell::JobManager::new(
                meerkat_tools::builtin::shell::ShellConfig::from_defaults(
                    &effective_config.shell,
                    project_root,
                ),
            )
            .bind_canonical_async_ops(session_id.clone(), ops_registry)
            .with_durable_job_runtime(durable),
        );
        let mut managers = self.monitor_job_managers.lock().await;
        Ok(Arc::clone(
            managers
                .entry(session_id.clone())
                .or_insert_with(|| manager),
        ))
    }

    /// Cancel a built-in durable shell/monitor runner with process containment.
    /// Returns `false` for non-built-in runners so their owning host protocol
    /// can handle cancellation.
    pub(crate) async fn cancel_local_durable_runner(
        self: &Arc<Self>,
        job_id: &meerkat::JobId,
    ) -> Result<bool, RpcError> {
        let Some(job) = self.job_store.get(job_id).await.map_err(|error| RpcError {
            code: error::INTERNAL_ERROR,
            message: error.to_string(),
            data: None,
        })?
        else {
            return Ok(false);
        };
        let Some(realm_id) = self.realm_id() else {
            return Ok(false);
        };
        if job.spec.realm_id != realm_id.as_str()
            || !matches!(
                job.spec.runner.name(),
                "meerkat.shell" | "meerkat.monitor_script"
            )
        {
            return Ok(false);
        }
        let manager = self
            .monitor_job_manager_for_session(&job.spec.origin_session_id)
            .await?;
        manager
            .cancel_job(&meerkat_tools::builtin::shell::JobId::from_string(
                job_id.to_string(),
            ))
            .await
            .map_err(|error| RpcError {
                code: error::INVALID_REQUEST,
                message: error.to_string(),
                data: None,
            })?;
        Ok(true)
    }

    /// Start the mechanical job-outbox/runtime-inbox delivery driver once.
    ///
    /// The driver never claims work or changes job lifecycle. It only performs
    /// the durable handoff and applies already-committed subscription effects.
    pub fn arm_job_delivery_driver(self: &Arc<Self>) {
        if self
            .job_delivery_driver_armed
            .compare_exchange(
                false,
                true,
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            )
            .is_err()
        {
            return;
        }
        let runtime = Arc::downgrade(self);
        tokio::spawn(async move {
            let mut backoff = JobDeliveryDriverBackoff::new();
            loop {
                let Some(runtime) = runtime.upgrade() else {
                    return;
                };
                let outcome = runtime.drain_job_deliveries().await;
                match &outcome {
                    Ok(summary) if !summary.failures.is_empty() => tracing::warn!(
                        failures = ?summary.failures,
                        "durable job delivery drain left rows pending"
                    ),
                    Ok(_) => {}
                    Err(error) => {
                        tracing::warn!(%error, "durable job delivery drain failed");
                    }
                }
                drop(runtime);
                tokio::time::sleep(backoff.observe_drain(&outcome)).await;
            }
        });
    }

    pub async fn drain_job_deliveries(self: &Arc<Self>) -> Result<JobDeliveryDrainSummary, String> {
        let _guard = self.job_delivery_drain_lock.lock().await;
        let mut summary = JobDeliveryDrainSummary::default();
        let realm_id = self
            .realm_id()
            .ok_or_else(|| "durable job delivery requires an active realm".to_string())?;
        let projector = meerkat::JobOutboxProjector::new_for_realm(
            self.job_store.clone(),
            self.runtime_delivery_inbox.clone(),
            realm_id.to_string(),
        );
        let projection = projector
            .project_pending(256)
            .await
            .map_err(|error| error.to_string())?;
        summary.projected = projection.projected.len();
        for skipped in projection.skipped {
            summary.failures.push(format!(
                "projection of job {} delivery {} failed: {}",
                skipped.job_id, skipped.delivery_sequence, skipped.error
            ));
        }

        let jobs = self
            .job_store
            .list_all(10_000)
            .await
            .map_err(|error| error.to_string())?;
        let mut sessions = BTreeMap::new();
        for job in jobs
            .into_iter()
            .filter(|job| job.spec.realm_id == realm_id.as_str())
        {
            let origin_session_id = job.spec.origin_session_id;
            sessions.insert(origin_session_id.to_string(), origin_session_id);
            for subscription in job.subscriptions {
                let session_id = subscription.session_id().clone();
                sessions.insert(session_id.to_string(), session_id);
            }
        }
        let base_sink: Arc<dyn meerkat::JobDeliverySink> =
            Arc::new(SessionRuntimeJobDeliverySink {
                runtime: Arc::clone(self),
            });
        for session_id in sessions.into_values() {
            let sink: Arc<dyn meerkat::JobDeliverySink> = match self
                .runtime_adapter
                .ops_lifecycle_registry(&session_id)
                .await
            {
                Some(operations) => Arc::new(meerkat::JobAwaitDeliverySink::new(
                    meerkat::JobAwaitCoordinator::new(
                        realm_id.to_string(),
                        self.detached_job_service(),
                        operations,
                    ),
                    base_sink.clone(),
                )),
                None => base_sink.clone(),
            };
            let applier =
                meerkat::JobRuntimeDeliveryApplier::new(self.runtime_delivery_inbox.clone(), sink);
            // Fail SAFE per session: one session's poisoned or unreadable
            // inbox must not head-of-line block every other session's
            // delivery drain. Nothing is discarded — failed rows stay
            // pending and retry on the next pass.
            match applier
                .apply_pending(
                    &meerkat_runtime::LogicalRuntimeId::for_session(&session_id),
                    256,
                )
                .await
            {
                Ok(drain) => {
                    summary.applied += drain.applied.len();
                    if let Some(blocked) = drain.blocked {
                        summary.failures.push(format!(
                            "delivery {} (sequence {}) for session {session_id} is blocked: {}",
                            blocked.delivery_id, blocked.runtime_sequence, blocked.error
                        ));
                    }
                }
                Err(error) => summary.failures.push(format!(
                    "delivery drain for session {session_id} failed: {error}"
                )),
            }
        }
        Ok(summary)
    }

    /// Committed-but-undrained runtime deliveries across this host's store.
    ///
    /// Asked of the delivery authority directly rather than of a session set
    /// derived from job rows. The derived set MISSES: job rows are read
    /// through a bounded window ordered by job id, so a session whose jobs
    /// aged out of that window still holds its undrained inbox rows and used
    /// to contribute nothing - accepted-and-undrained being the field symptom
    /// this probe exists to catch.
    ///
    /// The answer is host-store scoped rather than realm scoped; see
    /// [`meerkat_runtime::RuntimeDeliveryInbox::pending_delivery_total`].
    pub async fn runtime_job_delivery_backlog(&self) -> Result<u64, String> {
        self.runtime_delivery_inbox
            .pending_delivery_total()
            .await
            .map_err(|error| error.to_string())
    }

    /// Build the realm-scoped WorkGraph service.
    ///
    /// The store scope comes from the typed realm owner — never an invented
    /// `"default"` slug. A runtime without realm identity has no WorkGraph
    /// scope and fails closed.
    pub fn workgraph_service(&self) -> Result<meerkat::WorkGraphService, RpcError> {
        let realm_id = self
            .realm_id()
            .map(|realm_id| realm_id.to_string())
            .ok_or_else(|| RpcError {
                code: error::INTERNAL_ERROR,
                message: "WorkGraph requires a realm-scoped runtime; no realm identity is active"
                    .to_string(),
                data: None,
            })?;
        Ok(meerkat::WorkGraphService::with_scope(
            self.workgraph_store.clone(),
            realm_id,
            meerkat::WorkNamespace::default(),
        ))
    }

    pub fn blob_store(&self) -> Arc<dyn meerkat_core::BlobStore> {
        self.service.blob_store()
    }

    pub fn artifact_store(&self) -> Arc<dyn meerkat_core::ArtifactStore> {
        self.artifact_store.clone()
    }

    pub fn default_llm_client(&self) -> Option<Arc<dyn LlmClient>> {
        self.default_llm_client
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
    }

    /// Compose the active realm chain over the durable head config — the
    /// effective config every model-resolution read path (registry, create
    /// default-model) must use so an inherited (ancestor-realm) self-hosted alias
    /// or default model resolves like the agent build + hot-swap paths. The
    /// `config get/set` path keeps reading the RAW head store (read/write split).
    /// Fail-closed: a compose error propagates.
    pub async fn effective_config(&self) -> Result<meerkat_core::Config, RpcError> {
        let head_config = if let Some(runtime) = self.config_runtime() {
            runtime
                .get()
                .await
                .map(|snapshot| snapshot.config)
                .map_err(|e| RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!("Failed to load config: {e}"),
                    data: None,
                })?
        } else {
            meerkat_core::Config::default()
        };

        let inheritance = self
            .builder_realm_inheritance
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        if let Some(inheritance) = inheritance {
            inheritance
                .compose_over(head_config)
                .await
                .map_err(|e| RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!("Failed to compose realm config chain: {e}"),
                    data: None,
                })
        } else {
            Ok(head_config)
        }
    }

    async fn model_registry(&self) -> Result<meerkat_core::ModelRegistry, RpcError> {
        self.effective_config()
            .await?
            .model_registry(meerkat_models::canonical())
            .map_err(|e| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!("Failed to resolve model registry: {e}"),
                data: None,
            })
    }

    /// #61/#67: resolve the provider for a direct session create through
    /// registered model ownership, failing closed.
    ///
    /// This is the RPC mirror of REST's `resolve_validation_identity`
    /// (`meerkat-rest/src/lib.rs`): an explicit provider is validated against
    /// the catalog owner via `provider_override_mismatch_reason`; otherwise
    /// the registered model owner (`entry.provider`) supplies the provider.
    /// When neither an explicit provider nor a registered owner is present we
    /// return `INVALID_PARAMS` instead of inferring a provider from the model
    /// string — the surface never re-derives provider identity the registry
    /// is the owner of.
    async fn resolve_create_provider(
        &self,
        build_config: &AgentBuildConfig,
    ) -> Result<meerkat_core::Provider, RpcError> {
        let registry = self.model_registry().await?;
        let model = build_config.model.as_str();
        if let Some(provider) = build_config.provider {
            if let Some(reason) =
                registered_model_provider_mismatch_reason(&registry, provider, model)
            {
                return Err(RpcError {
                    code: error::INVALID_PARAMS,
                    message: reason,
                    data: None,
                });
            }
            return Ok(provider);
        }
        registry
            .entry(model)
            .map(|entry| entry.provider)
            .ok_or_else(|| RpcError {
                code: error::INVALID_PARAMS,
                message: format!(
                    "model '{model}' requires an explicit provider or a registered model owner"
                ),
                data: None,
            })
    }

    async fn wire_resolved_capabilities_for_identity(
        &self,
        identity: &SessionLlmIdentity,
    ) -> Option<meerkat_contracts::WireResolvedModelCapabilities> {
        let registry = self.model_registry().await.ok()?;
        let profile = registry.profile_for_provider(identity.provider, &identity.model)?;
        Some(profile_to_capability_surface(&profile).to_wire_resolved())
    }

    /// Resolve the wire capability surface for a materialized session.
    ///
    /// The session-owned resolved capability surface (recorded by the
    /// machine at build/hot-swap) is the only truth source here. `Ok(None)`
    /// is honest absence — no resolved surface recorded — and a machine
    /// fault propagates as a typed `RpcError`. The registry projection is
    /// never re-derived as a fallback: that would open a divergence window
    /// between the advertised capabilities and the session's actual
    /// resolution. (Staged sessions advertise the identity-derived
    /// projection explicitly via `wire_resolved_capabilities_for_identity`
    /// before a resolution exists.)
    async fn wire_resolved_capabilities_for_session(
        &self,
        session_id: &SessionId,
    ) -> Result<Option<meerkat_contracts::WireResolvedModelCapabilities>, RpcError> {
        match self
            .runtime_adapter
            .resolved_session_llm_capabilities(session_id)
            .await
        {
            Ok(surface) => Ok(surface.map(|surface| surface.to_wire_resolved())),
            // An absent or terminal runtime (archived/destroyed/never bound)
            // has no machine-resolved capability surface; `None` is the honest
            // absence answer, mirroring the staged-session pre-resolution
            // path. Reads of archived sessions remain available.
            Err(
                meerkat_runtime::RuntimeDriverError::NotFound { .. }
                | meerkat_runtime::RuntimeDriverError::Destroyed
                | meerkat_runtime::RuntimeDriverError::NotReady { .. },
            ) => Ok(None),
            // Any other fault is a genuine control-plane failure and must not
            // be laundered into a capability-free success.
            Err(err) => Err(RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "failed to read resolved llm capabilities for session {session_id}: {err}"
                ),
                data: None,
            }),
        }
    }

    async fn attach_resolved_capabilities_to_wire_info(
        &self,
        info: &mut meerkat_contracts::WireSessionInfo,
    ) -> Result<(), RpcError> {
        info.resolved_capabilities = self
            .wire_resolved_capabilities_for_session(&info.session_id)
            .await?;
        Ok(())
    }

    async fn llm_identity_from_pending_build(
        &self,
        build_config: &AgentBuildConfig,
    ) -> Result<SessionLlmIdentity, RpcError> {
        let registry = self.model_registry().await?;
        let model = build_config.model.clone();
        let provider = self.resolve_create_provider(build_config).await?;
        let self_hosted_server_id = if provider == meerkat_core::Provider::SelfHosted {
            if let Some(server_id) = build_config.self_hosted_server_id.clone() {
                Some(server_id)
            } else if let Some(metadata) = build_config
                .resume_session
                .as_ref()
                .and_then(Session::session_metadata)
            {
                metadata.self_hosted_server_id
            } else if let Some(entry) =
                registry.entry_for_provider(meerkat_core::Provider::SelfHosted, &model)
            {
                entry
                    .self_hosted
                    .as_ref()
                    .map(|server| server.server_id.clone())
            } else {
                return Err(RpcError {
                    code: error::INVALID_PARAMS,
                    message: format!(
                        "self-hosted provider requires a registered model alias; '{model}' is not configured"
                    ),
                    data: None,
                });
            }
        } else {
            None
        };
        Ok(SessionLlmIdentity {
            model,
            provider,
            self_hosted_server_id,
            provider_params: build_config.provider_params.clone(),
            auth_binding: build_config.auth_binding.clone(),
        })
    }

    async fn provider_supports_inline_video(&self, identity: &SessionLlmIdentity) -> bool {
        self.require_inline_video_support(identity).await.is_ok()
    }

    async fn require_inline_video_support(
        &self,
        identity: &SessionLlmIdentity,
    ) -> Result<(), meerkat_core::UnsupportedModelCapabilityEvidence> {
        let Ok(registry) = self.model_registry().await else {
            return Err(
                meerkat_core::UnsupportedModelCapabilityEvidence::inline_video(
                    identity.provider,
                    identity.model.clone(),
                    meerkat_core::UnsupportedModelCapabilityReason::CapabilityRegistryUnavailable,
                ),
            );
        };

        registry.require_inline_video_for_provider(identity.provider, &identity.model)
    }

    async fn validate_prompt_video_input(
        &self,
        prompt: &ContentInput,
        identity: &SessionLlmIdentity,
    ) -> Result<(), RpcError> {
        let blocks = match prompt {
            ContentInput::Text(_) => return Ok(()),
            ContentInput::Blocks(blocks) => blocks,
        };

        meerkat_core::validate_inline_video_blocks(blocks).map_err(|message| RpcError {
            code: error::INVALID_PARAMS,
            message,
            data: None,
        })?;

        if meerkat_core::has_video(blocks)
            && let Err(evidence) = self.require_inline_video_support(identity).await
        {
            return Err(unsupported_model_capability_rpc_error(evidence));
        }

        Ok(())
    }

    async fn resolve_target_llm_identity(
        &self,
        current: &SessionLlmIdentity,
        ov: &crate::handlers::turn::TurnOverrides,
    ) -> Result<SessionLlmIdentity, RpcError> {
        let registry = self.model_registry().await?;
        let provider = ov
            .provider
            .as_deref()
            .map(parse_provider_override)
            .transpose()
            .map_err(|message| RpcError {
                code: error::INVALID_PARAMS,
                message,
                data: None,
            })?;

        meerkat_core::resolve_session_llm_identity_override(
            current,
            &registry,
            SessionLlmIdentityOverride {
                model: ov.model.as_deref(),
                provider,
                self_hosted_server_id: ov.self_hosted_server_id.as_deref(),
                provider_params: ov
                    .provider_params
                    .as_ref()
                    .map(meerkat_core::lifecycle::run_primitive::TurnMetadataOverride::as_ref),
                auth_binding: ov
                    .auth_binding
                    .as_ref()
                    .map(meerkat_core::lifecycle::run_primitive::TurnMetadataOverride::as_ref),
            },
        )
        .map_err(|err| RpcError {
            code: error::INVALID_PARAMS,
            message: err.to_string(),
            data: None,
        })
    }

    fn apply_llm_identity_to_build_config(
        build_config: &mut AgentBuildConfig,
        identity: &SessionLlmIdentity,
    ) {
        build_config.model = identity.model.clone();
        build_config.provider = Some(identity.provider);
        build_config.self_hosted_server_id = identity.self_hosted_server_id.clone();
        build_config.provider_params = identity.provider_params.clone();
        build_config.auth_binding = identity.auth_binding.clone();
    }

    async fn current_materialized_llm_identity(
        &self,
        session_id: &SessionId,
    ) -> Result<SessionLlmIdentity, RpcError> {
        match self.service.live_session_llm_identity(session_id).await {
            Ok(identity) => Ok(identity),
            Err(SessionError::NotFound { .. }) => {
                let session = self
                    .load_persisted_session(session_id)
                    .await?
                    .ok_or_else(|| RpcError {
                        code: error::SESSION_NOT_FOUND,
                        message: format!("session not found: {session_id}"),
                        data: None,
                    })?;
                let metadata = session.session_metadata().ok_or_else(|| RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!(
                        "session {session_id} is missing durable llm identity metadata"
                    ),
                    data: None,
                })?;
                Ok(metadata.llm_identity())
            }
            Err(err) => Err(session_error_to_rpc(err)),
        }
    }

    async fn effective_llm_identity_for_turn(
        &self,
        session_id: &SessionId,
        overrides: Option<&crate::handlers::turn::TurnOverrides>,
    ) -> Result<SessionLlmIdentity, RpcError> {
        let pending_identity = self
            .staged_sessions
            .effective_llm_identity(session_id)
            .await
            .map_err(|err| RpcError {
                code: error::INTERNAL_ERROR,
                message: err.to_string(),
                data: None,
            })?;
        if let Some(pending_identity) = pending_identity {
            return match overrides {
                Some(ov) => {
                    self.resolve_target_llm_identity(&pending_identity, ov)
                        .await
                }
                None => Ok(pending_identity),
            };
        }

        let current = self.current_materialized_llm_identity(session_id).await?;
        match overrides {
            Some(ov) => self.resolve_target_llm_identity(&current, ov).await,
            None => Ok(current),
        }
    }

    fn llm_reconfigure_host(&self) -> SessionRuntimeLlmReconfigureHost {
        SessionRuntimeLlmReconfigureHost {
            service: self.service.clone(),
            staged_sessions: Arc::clone(&self.staged_sessions),
            factory: self.factory.clone(),
            auth_lease: self.runtime_adapter.generated_auth_lease_handle(),
            default_llm_client: Arc::clone(&self.default_llm_client),
            agent_llm_client_decorator: Arc::clone(&self.agent_llm_client_decorator),
            config_runtime: Arc::clone(&self.config_runtime),
            realm_inheritance: Arc::clone(&self.builder_realm_inheritance),
        }
    }

    /// Hot-swap the LLM client on a materialized session.
    ///
    /// The machine owns the semantic transition; RPC only adapts the request.
    async fn hot_swap_llm_client(
        &self,
        session_id: &SessionId,
        ov: &crate::handlers::turn::TurnOverrides,
    ) -> Result<(), RpcError> {
        self.hot_swap_llm_client_with_boundary_ownership(
            session_id,
            ov,
            LlmReconfigureBoundaryOwnership::Acquire,
        )
        .await
    }

    async fn hot_swap_llm_client_under_turn_finalization_boundary(
        &self,
        session_id: &SessionId,
        ov: &crate::handlers::turn::TurnOverrides,
    ) -> Result<(), RpcError> {
        self.hot_swap_llm_client_with_boundary_ownership(
            session_id,
            ov,
            LlmReconfigureBoundaryOwnership::AlreadyHeld,
        )
        .await
    }

    async fn hot_swap_llm_client_with_boundary_ownership(
        &self,
        session_id: &SessionId,
        ov: &crate::handlers::turn::TurnOverrides,
        boundary_ownership: LlmReconfigureBoundaryOwnership,
    ) -> Result<(), RpcError> {
        let request = SessionLlmReconfigureRequest {
            model: ov.model.clone(),
            provider: ov.provider.clone(),
            self_hosted_server_id: ov.self_hosted_server_id.clone(),
            provider_params: ov.provider_params.clone(),
            auth_binding: ov.auth_binding.clone(),
        };

        let live_session_exists = match self.service.has_live_session(session_id).await {
            Ok(exists) => exists,
            Err(SessionError::NotFound { .. }) => false,
            Err(error) => return Err(session_error_to_rpc(error)),
        };
        if !self.runtime_adapter.contains_session(session_id).await && live_session_exists {
            self.runtime_adapter
                .prepare_bindings(session_id.clone())
                .await
                .map_err(|e| RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!(
                        "failed to prepare runtime bindings for live session {session_id}: {e}"
                    ),
                    data: None,
                })?;
        }

        let reconfigure = match boundary_ownership {
            LlmReconfigureBoundaryOwnership::Acquire => {
                self.runtime_adapter
                    .reconfigure_session_llm_identity(session_id, request)
                    .await
            }
            LlmReconfigureBoundaryOwnership::AlreadyHeld => {
                self.runtime_adapter
                    .reconfigure_session_llm_identity_under_turn_finalization_boundary(
                        session_id, request,
                    )
                    .await
            }
        };
        let report = match reconfigure {
            Ok(report) => report,
            Err(err) => return Err(runtime_driver_error_to_rpc(err)),
        };

        if live_channel_requires_close_for_identity_change(
            &report.previous_identity,
            &report.new_identity,
        ) {
            let snapshot = self.realm_context_snapshot();
            let cleanup = self.archive_runtime_cleanup();
            let close_report = self
                .live_orchestrator(&snapshot, cleanup)
                .close_live_channels_for_identity_change(session_id, &report.new_identity)
                .await;
            if !close_report.close_failed.is_empty() {
                return Err(RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!(
                        "failed to close stale live channel after LLM identity change for {session_id}: {:?}",
                        close_report.close_failed
                    ),
                    data: None,
                });
            }
        }

        Ok(())
    }

