    /// A committed archived successor refuses ingress as `SESSION_NOT_FOUND`.
    /// The wire code is the contract; the two prose forms ("session not
    /// found" and "requires canonical runtime teardown") are the same typed
    /// refusal and must never be what a test (or a caller) classifies on.
    fn refuses_as_session_absent(err: &RpcError) -> bool {
        err.code == error::SESSION_NOT_FOUND
    }

    fn has_terminal_peer_response_notice(
        messages: &[Message],
        expected_peer_id: &str,
        expected_request_id: &str,
        expected_token: &str,
    ) -> bool {
        messages.iter().any(|message| {
            let Message::SystemNotice(notice) = message else {
                return false;
            };
            notice.blocks.iter().any(|block| {
                let meerkat_core::types::SystemNoticeBlock::Comms {
                    kind,
                    peer,
                    request_id,
                    payload,
                    ..
                } = block
                else {
                    return false;
                };
                *kind == meerkat_core::types::CommsNoticeKind::ResponseTerminal
                    && peer
                        .as_ref()
                        .is_some_and(|peer| peer.id.to_string() == expected_peer_id)
                    && request_id.as_deref() == Some(expected_request_id)
                    && payload
                        .as_ref()
                        .and_then(|payload| payload.get("token"))
                        .and_then(serde_json::Value::as_str)
                        == Some(expected_token)
            })
        })
    }

