    fn make_runtime_with_failing_runtime_store(
        factory: AgentFactory,
        max_sessions: usize,
    ) -> (Arc<SessionRuntime>, Arc<FailingLifecycleRuntimeStore>) {
        let session_store: Arc<dyn meerkat::SessionStore> = Arc::new(meerkat::MemoryStore::new());
        let runtime_store = Arc::new(FailingLifecycleRuntimeStore::new());
        let runtime_store_dyn: Arc<dyn meerkat_runtime::RuntimeStore> = runtime_store.clone();
        let blob_store: Arc<dyn meerkat_core::BlobStore> =
            Arc::new(meerkat_store::MemoryBlobStore::new());
        (
            Arc::new(SessionRuntime::new(
                factory,
                Config::default(),
                max_sessions,
                meerkat::PersistenceBundle::new(session_store, runtime_store_dyn, blob_store),
                crate::router::NotificationSink::noop(),
            )),
            runtime_store,
        )
    }

    #[tokio::test]
    async fn rpc_new_runtime_compensation_combines_cleanup_failure_and_remains_retryable() {
        let temp = tempfile::tempdir().expect("tempdir");
        let session_store: Arc<dyn meerkat::SessionStore> = Arc::new(meerkat::MemoryStore::new());
        let runtime_store = Arc::new(FailingLifecycleRuntimeStore::new());
        let runtime_store_dyn: Arc<dyn meerkat_runtime::RuntimeStore> = runtime_store.clone();
        let blob_store: Arc<dyn meerkat_core::BlobStore> =
            Arc::new(meerkat_store::MemoryBlobStore::new());
        let runtime = Arc::new(SessionRuntime::new(
            temp_factory(&temp),
            Config::default(),
            1,
            meerkat::PersistenceBundle::new(session_store, runtime_store_dyn, blob_store),
            crate::router::NotificationSink::noop(),
        ));
        let session_id = SessionId::new();
        let runtime_id = meerkat_runtime::LogicalRuntimeId::for_session(&session_id);
        let snapshot = meerkat_runtime::ops_lifecycle::RuntimeOpsLifecycleRegistry::new()
            .capture_persistence_snapshot(
                meerkat_core::RuntimeEpochId::new(),
                &meerkat_core::EpochCursorState::new(),
            )
            .expect("capture ops lifecycle snapshot");
        meerkat_runtime::RuntimeStore::persist_ops_lifecycle(
            runtime_store.as_ref(),
            &runtime_id,
            &snapshot,
        )
        .await
        .expect("persist ops lifecycle snapshot");
        runtime
            .runtime_adapter
            .register_session(session_id.clone())
            .await
            .expect("register persistent runtime");
        runtime_store.fail_next_delete_ops_lifecycle();

        let error = runtime
            .unregister_new_runtime_registration_after_rpc_error(
                &runtime.runtime_adapter,
                &session_id,
                false,
                false,
                false,
                RpcError {
                    code: error::INTERNAL_ERROR,
                    message: "synthetic RPC materialization failure".to_string(),
                    data: None,
                },
            )
            .await;
        assert!(
            error
                .message
                .contains("synthetic RPC materialization failure"),
            "combined error must retain primary failure: {}",
            error.message
        );
        assert!(
            error
                .message
                .contains("synthetic RPC unregister cleanup failure"),
            "combined error must retain cleanup failure: {}",
            error.message
        );
        assert!(
            runtime.runtime_adapter.contains_session(&session_id).await,
            "failed durable unregister must retain runtime registration for retry"
        );

        runtime
            .unregister_new_runtime_registration_if_idle(
                &runtime.runtime_adapter,
                &session_id,
                false,
                false,
                false,
            )
            .await
            .expect("retry should complete retained unregister work");
        assert!(
            !runtime.runtime_adapter.contains_session(&session_id).await,
            "successful retry must remove runtime registration"
        );
    }

    #[async_trait]
    impl LlmClient for BlockingMockLlmClient {
        fn project_replay_messages(
            &self,
            messages: &[meerkat_core::Message],
        ) -> Result<Vec<meerkat_core::Message>, meerkat_client::LlmError> {
            Ok(messages.to_vec())
        }

        fn stream<'a>(
            &'a self,
            request: &'a meerkat_client::LlmRequest,
        ) -> Pin<
            Box<dyn futures::Stream<Item = Result<meerkat_client::LlmEvent, LlmError>> + Send + 'a>,
        > {
            let calls = Arc::clone(&self.calls);
            let release = Arc::clone(&self.release);
            Box::pin(async_stream::stream! {
                calls.record();
                release.notified().await;
                yield Ok(meerkat_client::LlmEvent::TextDelta {
                    delta: "Blocked response".to_string(),
                    meta: None,
                });
                yield Ok(meerkat_client::LlmEvent::UsageUpdate {
                    usage: meerkat_core::TurnUsage::host_declared(
                        provider_for_successful_rpc_test_model(&request.model),
                        &request.model,
                        meerkat_core::Usage::default(),
                    ),
                });
                yield Ok(meerkat_client::LlmEvent::Done {
                    outcome: meerkat_client::LlmDoneOutcome::Success {
                        stop_reason: StopReason::EndTurn,
                    },
                });
            })
        }

        fn provider(&self) -> meerkat_core::Provider {
            meerkat_core::Provider::Other
        }

        async fn health_check(&self) -> Result<(), LlmError> {
            Ok(())
        }
    }

    struct BlockAfterFirstMockLlmClient {
        calls: Arc<BlockingLlmCallWitness>,
        release: Arc<Notify>,
    }

    #[async_trait]
    impl LlmClient for BlockAfterFirstMockLlmClient {
        fn project_replay_messages(
            &self,
            messages: &[meerkat_core::Message],
        ) -> Result<Vec<meerkat_core::Message>, LlmError> {
            Ok(messages.to_vec())
        }

        fn stream<'a>(
            &'a self,
            request: &'a meerkat_client::LlmRequest,
        ) -> Pin<
            Box<dyn futures::Stream<Item = Result<meerkat_client::LlmEvent, LlmError>> + Send + 'a>,
        > {
            let call = self.calls.record();
            let release = Arc::clone(&self.release);
            Box::pin(async_stream::stream! {
                if call > 0 {
                    release.notified().await;
                }
                yield Ok(meerkat_client::LlmEvent::TextDelta {
                    delta: "Slow response".to_string(),
                    meta: None,
                });
                yield Ok(meerkat_client::LlmEvent::UsageUpdate {
                    usage: meerkat_core::TurnUsage::host_declared(
                        provider_for_successful_rpc_test_model(&request.model),
                        &request.model,
                        meerkat_core::Usage::default(),
                    ),
                });
                yield Ok(meerkat_client::LlmEvent::Done {
                    outcome: meerkat_client::LlmDoneOutcome::Success {
                        stop_reason: StopReason::EndTurn,
                    },
                });
            })
        }

        fn provider(&self) -> meerkat_core::Provider {
            meerkat_core::Provider::Other
        }

        async fn health_check(&self) -> Result<(), LlmError> {
            Ok(())
        }
    }

    struct FailAfterFirstMockLlmClient {
        calls: AtomicUsize,
    }

    impl FailAfterFirstMockLlmClient {
        fn new() -> Self {
            Self {
                calls: AtomicUsize::new(0),
            }
        }
    }

    #[async_trait]
    impl LlmClient for FailAfterFirstMockLlmClient {
        fn project_replay_messages(
            &self,
            messages: &[meerkat_core::Message],
        ) -> Result<Vec<meerkat_core::Message>, meerkat_client::LlmError> {
            Ok(messages.to_vec())
        }

        fn stream<'a>(
            &'a self,
            request: &'a meerkat_client::LlmRequest,
        ) -> Pin<
            Box<dyn futures::Stream<Item = Result<meerkat_client::LlmEvent, LlmError>> + Send + 'a>,
        > {
            let call = self.calls.fetch_add(1, AtomicOrdering::SeqCst);
            if call == 0 {
                Box::pin(stream::iter(vec![
                    Ok(meerkat_client::LlmEvent::TextDelta {
                        delta: "first turn succeeds".to_string(),
                        meta: None,
                    }),
                    Ok(meerkat_client::LlmEvent::UsageUpdate {
                        usage: meerkat_core::TurnUsage::host_declared(
                            provider_for_successful_rpc_test_model(&request.model),
                            &request.model,
                            meerkat_core::Usage::default(),
                        ),
                    }),
                    Ok(meerkat_client::LlmEvent::Done {
                        outcome: meerkat_client::LlmDoneOutcome::Success {
                            stop_reason: StopReason::EndTurn,
                        },
                    }),
                ]))
            } else {
                Box::pin(stream::iter(vec![Err(LlmError::InvalidRequest {
                    message: "synthetic turn failure".to_string(),
                })]))
            }
        }

        fn provider(&self) -> meerkat_core::Provider {
            meerkat_core::Provider::Other
        }

        async fn health_check(&self) -> Result<(), LlmError> {
            Ok(())
        }
    }

