    #[tokio::test]
    async fn pending_start_create_authority_failure_restores_staged_admission() {
        let temp = tempfile::tempdir().unwrap();
        let (runtime, runtime_store) =
            make_runtime_with_failing_runtime_store(temp_factory(&temp), 1);

        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .expect("create staged session");
        runtime_store.set_fail_snapshot(true);
        let (event_tx, _event_rx) = mpsc::channel(100);
        let failed = runtime
            .start_turn(
                &session_id,
                "first materialization should fail durable save".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await;
        assert!(
            failed.as_ref().err().is_some_and(|err| err
                .message
                .contains("forced RuntimeStore session-boundary failure")),
            "create boundary failure should be surfaced for pending start: {failed:?}"
        );
        let blocked = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await;
        assert!(
            blocked
                .as_ref()
                .err()
                .is_some_and(|err| err.message.contains("Max sessions")),
            "restored staged session must keep admission reserved after create failure: {blocked:?}"
        );
        assert!(
            !runtime
                .service
                .has_live_session(&session_id)
                .await
                .expect("query live session after create failure"),
            "failed pending create should discard the unpersisted live deferred session"
        );

        runtime_store.clear_snapshot_failures();
        let (event_tx, _event_rx) = mpsc::channel(100);
        runtime
            .start_turn(
                &session_id,
                "retry after create persist failure".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await
            .expect("staged session should retry after durable store recovers");
        runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .expect("completed retry should release active admission");
    }

