    #[tokio::test]
    async fn recovered_runtime_apply_pre_run_terminal_discards_live_deferred_session() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 1);
        runtime.set_default_llm_client(Some(Arc::new(MockLlmClient)));
        let runtime = Arc::new(runtime);

        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .expect("create recoverable session");
        let (event_tx, _event_rx) = mpsc::channel(100);
        runtime
            .start_turn(
                &session_id,
                "persist me".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await
            .expect("complete recoverable session");
        runtime
            .service
            .discard_live_session(&session_id)
            .await
            .expect("discard live recoverable session");
        assert!(
            runtime.runtime_adapter.contains_session(&session_id).await,
            "discarding the live session should leave a stale runtime registration for recovery cleanup"
        );

        let primitive = runtime_resume_pending_primitive();
        let (event_tx, _event_rx) = mpsc::channel(100);
        let output = runtime
            .apply_runtime_turn(
                &session_id,
                RunId::new(),
                &primitive,
                ContentInput::Text(String::new()),
                event_tx,
                None,
                None,
            )
            .await
            .expect("recovered no-pending boundary should be returned as a typed terminal");
        assert!(
            matches!(output.terminal, Some(CoreApplyTerminal::NoPendingBoundary)),
            "recovered resume-pending without a boundary should return no-pending terminal: {output:?}"
        );
        assert!(
            runtime
                .service
                .has_live_session(&session_id)
                .await
                .expect("query live recovered session before handoff cleanup"),
            "direct apply must retain the recovered live session until the exact executor is handed off"
        );
        let actor_witness = runtime
            .runtime_actor_witness(&session_id)
            .expect("recovered session must retain exact actor authority");
        let mut executor = crate::session_executor::SessionRuntimeExecutor::new(
            Arc::clone(&runtime),
            actor_witness,
        );
        meerkat_core::lifecycle::CoreExecutor::cleanup_after_runtime_stop_terminalized(
            &mut executor,
        )
        .await
        .expect("post-handoff RPC executor cleanup should discard the recovered live session");
        assert!(
            !runtime
                .service
                .has_live_session(&session_id)
                .await
                .expect("query live recovered session"),
            "recovered pre-run terminal must not leave an untracked live deferred session"
        );
        assert!(
            runtime.runtime_adapter.contains_session(&session_id).await,
            "external executor cleanup must retain registration for the machine-owned unregister saga"
        );
        runtime
            .runtime_adapter
            .unregister_session(&session_id)
            .await
            .expect("test should drive the post-handoff unregister saga");

        runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .expect("recovered pre-run terminal should release active admission");
    }

