    #[tokio::test]
    async fn recovered_runtime_apply_create_authority_failure_discards_live_deferred_admission() {
        let temp = tempfile::tempdir().unwrap();
        let (runtime, runtime_store) =
            make_runtime_with_failing_runtime_store(temp_factory(&temp), 1);
        runtime.set_default_llm_client(Some(Arc::new(MockLlmClient)));
        let runtime = Arc::new(runtime);

        let service = runtime.session_service();
        let direct = service
            .create_session(service_create_request(
                mock_build_config(),
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("direct deferred create should author runtime-backed recovery state");
        let session_id = direct.session_id;
        runtime
            .service
            .discard_live_session(&session_id)
            .await
            .expect("discard live session to force runtime-backed recovery");
        runtime
            .runtime_adapter
            .unregister_session(&session_id)
            .await
            .expect("runtime session should unregister cleanly");

        runtime_store.set_fail_snapshot(true);
        let primitive = runtime_content_turn_primitive();
        let (event_tx, _event_rx) = mpsc::channel(100);
        let failed = runtime
            .apply_runtime_turn(
                &session_id,
                RunId::new(),
                &primitive,
                ContentInput::Text("first recovery should fail durable save".to_string()),
                event_tx,
                None,
                None,
            )
            .await;
        assert!(
            failed.as_ref().err().is_some_and(|err| err
                .message
                .contains("forced RuntimeStore session-boundary failure")),
            "recovered create boundary failure should be surfaced: {failed:?}"
        );
        assert!(
            !runtime
                .service
                .has_live_session(&session_id)
                .await
                .expect("query live recovered session after create failure"),
            "failed recovered create should discard the unpersisted live deferred session"
        );

        runtime_store.clear_snapshot_failures();
        let admitted = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .expect("discarded recovered create failure should release admission");
        runtime
            .archive_session(&admitted)
            .await
            .expect("archive admitted control session before retrying recovery");

        let primitive = runtime_content_turn_primitive();
        let (event_tx, _event_rx) = mpsc::channel(100);
        runtime
            .apply_runtime_turn(
                &session_id,
                RunId::new(),
                &primitive,
                ContentInput::Text("retry recovery after durable store recovers".to_string()),
                event_tx,
                None,
                None,
            )
            .await
            .expect("recovered session should retry after durable store recovers");
        runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .expect("completed recovery retry should release active admission");
    }

