    /// Wave-3 regression: a deferred session created with no first turn lives
    /// in `staged_sessions` and is **not** in the live service map, **not** in
    /// the persistent store. `precheck_live_open` must read identity directly
    /// from staging in that case; otherwise the live-map miss surfaces as
    /// `SessionLookup` (`INTERNAL_ERROR "session not found"`) before the B18
    /// (provider) and B19 (realtime-capability) gates can fire — the
    /// production-shape failure mode that the original Wave-3 fix didn't
    /// catch (the early `recover_live_session_for_realtime_open` dance only
    /// helped when the session was already persisted).
    ///
    /// To make sure this regression test exercises the production-shaped seam
    /// rather than a `MemoryStore` happy path, we assert before the precheck
    /// that the session is in `staged_sessions` and **not** yet in the live
    /// service map. That mirrors how `rkat-rpc` lands a deferred session:
    /// staged-only until the first turn promotes it.
    #[tokio::test]
    async fn precheck_live_open_recovers_deferred_realtime_session() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);

        let mut build = AgentBuildConfig::new("gpt-realtime-2");
        build.provider = Some(meerkat_core::Provider::OpenAI);
        build.llm_client_override = Some(Arc::new(MockLlmClient));
        let session_id = runtime
            .create_session(build, None, None, Vec::new())
            .await
            .expect("create_session for deferred OpenAI realtime build");

        // Production-shape pre-assertion: deferred session must be staged-only.
        assert!(
            runtime.staged_sessions.contains(&session_id).await,
            "deferred session must land in staged_sessions"
        );
        assert!(
            matches!(
                runtime.service.live_session_llm_identity(&session_id).await,
                Err(SessionError::NotFound { .. })
            ),
            "deferred session must NOT be in the live service map yet — \
             otherwise the precheck staged-branch is not exercised"
        );

        runtime
            .precheck_live_open(&session_id)
            .await
            .expect("deferred realtime session must pass precheck via staged branch");
    }

    #[tokio::test]
    async fn precheck_live_open_rejects_deferred_non_realtime_session() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);

        // claude-sonnet-4-5 is catalogued with `realtime: false`. The
        // staged branch of `precheck_live_open` must read the identity from
        // staging and the B19 model-capability gate must reject it with a
        // typed `ModelNotRealtime` — not `SessionLookup`. Asserting on the
        // typed variant guards against a regression where the staged read
        // silently swallows the gate error.
        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .expect("create_session for deferred non-realtime build");

        // Production-shape pre-assertion: deferred non-realtime session must
        // also be staged-only, so the gate test exercises the staged branch.
        assert!(
            runtime.staged_sessions.contains(&session_id).await,
            "deferred session must land in staged_sessions"
        );
        assert!(
            matches!(
                runtime.service.live_session_llm_identity(&session_id).await,
                Err(SessionError::NotFound { .. })
            ),
            "deferred session must NOT be in the live service map yet"
        );

        let err = runtime
            .precheck_live_open(&session_id)
            .await
            .expect_err("non-realtime model must be rejected by precheck");
        assert!(
            matches!(err, LiveOpenPrecheckError::ModelNotRealtime { .. }),
            "expected ModelNotRealtime, got {err:?}"
        );
    }

    /// #302: `live/open` must fail closed when no realtime session factory is
    /// wired into the build. Before the fix, `open_channel_with_authority`
    /// minted a channel regardless of factory presence, then returned a
    /// `channel_id` + bootstrap with all-false capabilities that rejected
    /// every real command later. The handler now refuses the open *before*
    /// any admission/channel is resolved — it returns a typed
    /// `INTERNAL_ERROR` and the response carries no `result` (no `channel_id`,
    /// no transport bootstrap), proving no channel was registered or opened.
    #[tokio::test]
    async fn live_open_without_session_factory_fails_closed_and_opens_no_channel() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);

        // Materialize a realtime-capable session so the B17 existence check
        // passes and the flow reaches the #302 no-factory guard.
        let mut build = AgentBuildConfig::new("gpt-realtime-2");
        build.provider = Some(meerkat_core::Provider::OpenAI);
        build.llm_client_override = Some(Arc::new(MockLlmClient));
        let session_id = runtime
            .create_session(build, None, None, Vec::new())
            .await
            .expect("create_session for realtime build");

        // A fresh host starts with no channels; the assertion below proves it
        // stays that way because the handler returns before opening one. The
        // #302 guard fires before any transport branch runs, so `live_ws` is
        // never read on this path — pass `None` and skip the heavyweight
        // `LiveWsState` fixture.
        let host = meerkat_live::LiveAdapterHost::new(Arc::new(meerkat_live::NoOpProjectionSink));

        let params = serde_json::value::to_raw_value(&serde_json::json!({
            "session_id": session_id.to_string(),
        }))
        .expect("serialize live/open params");

        #[cfg(all(feature = "experimental-gpt-live", feature = "live-webrtc"))]
        let experimental_live_playback_custodies =
            Arc::new(tokio::sync::Mutex::new(std::collections::HashMap::new()));

        let ctx = crate::handlers::live::LiveOpenHandlerContext {
            host: &host,
            live_ws: None,
            live_ws_base_url: None,
            #[cfg(feature = "live-webrtc")]
            live_webrtc: None,
            runtime: &runtime,
            // The whole point of #302: no factory wired.
            session_factory: None,
            #[cfg(feature = "experimental-gpt-live")]
            experimental_live_open_authority: None,
            #[cfg(all(feature = "experimental-gpt-live", feature = "live-webrtc"))]
            experimental_live_playback_custodies: &experimental_live_playback_custodies,
        };

        let response =
            crate::handlers::live::handle_live_open(None, Some(params.as_ref()), ctx).await;

        // Typed error, not a success carrying a channel id.
        let err = response
            .error
            .expect("no-factory live/open must return a typed error");
        assert_eq!(
            err.code,
            error::INTERNAL_ERROR,
            "no-factory live/open must fail with INTERNAL_ERROR, got {err:?}"
        );
        assert!(
            err.message.contains("realtime session factory"),
            "error must name the missing realtime session factory, got: {}",
            err.message
        );
        // No result payload means no channel_id / transport bootstrap was ever
        // handed back — the admission/open path never ran.
        assert!(
            response.result.is_none(),
            "no-factory live/open must not return a result payload (no channel opened)"
        );

        // Direct host evidence: a `random_uuid` close-reserve would only ever
        // succeed against a registered channel. The handler opened none, so
        // any probe resolves to `ChannelNotFound` — there is no orphaned
        // channel left behind.
        let probe = meerkat_live::LiveChannelId::random_uuid();
        assert!(
            matches!(
                host.reserve_channel_close_observation(&probe).await,
                Err(meerkat_live::LiveAdapterHostError::ChannelNotFound(_))
            ),
            "host must hold no live channels after a fail-closed no-factory open"
        );
    }

