    // Gate (#98): a RuntimeStore failure on the authoritative read path must
    // surface as a typed RpcError, NOT be collapsed into `Ok(None)` (which the
    // wire handler presents as SESSION_NOT_FOUND). SessionStore is only a
    // compatibility projection and is deliberately not consulted here.
    #[tokio::test]
    async fn gate_read_session_rich_surfaces_store_failure_as_error_not_not_found() {
        let temp = tempfile::tempdir().unwrap();
        let session_store: Arc<dyn meerkat::SessionStore> = Arc::new(meerkat::MemoryStore::new());
        let runtime_store = Arc::new(FailingLifecycleRuntimeStore::new());
        let runtime = Arc::new(SessionRuntime::new(
            temp_factory(&temp),
            Config::default(),
            10,
            meerkat::PersistenceBundle::new(
                session_store,
                runtime_store.clone(),
                Arc::new(meerkat_store::MemoryBlobStore::new()),
            ),
            crate::router::NotificationSink::noop(),
        ));
        runtime_store.fail_next_catalog_read();

        // No session was created. The RuntimeStore-owned catalog read itself
        // fails, so absence must not be fabricated from that failed probe.
        let unknown = SessionId::new();
        let result = runtime.read_session_rich(&unknown).await;

        match result {
            Ok(None) => panic!(
                "store load failure must NOT be laundered into a not-found (Ok(None)); \
                 it must surface as a typed RpcError"
            ),
            Ok(Some(_)) => panic!("unexpected session payload for a failing store"),
            Err(err) => {
                // A store fault is a control-plane failure, never a not-found.
                // The exact code depends on which authoritative store call
                // fails first, but it must never be laundered into not-found.
                assert_ne!(
                    err.code,
                    error::SESSION_NOT_FOUND,
                    "store failure must not be reported as SESSION_NOT_FOUND, got: {err:?}"
                );
            }
        }
    }

    // Gate (#98): a genuine not-found must still be reported as `Ok(None)` so
    // the fix distinguishes "session does not exist" from "store failed".
    #[tokio::test]
    async fn gate_read_session_rich_genuine_not_found_stays_ok_none() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);

        let unknown = SessionId::new();
        let result = runtime.read_session_rich(&unknown).await;
        assert!(
            matches!(result, Ok(None)),
            "a genuinely absent session must be reported as Ok(None), got: {result:?}"
        );
    }

    fn temp_factory_with_builtins(temp: &tempfile::TempDir) -> AgentFactory {
        AgentFactory::new(temp.path().join("sessions")).builtins(true)
    }

    /// After hot-swapping from an Anthropic model to an OpenAI Responses model,
    /// the machine-owned capability filter should keep `view_image` available.
    #[tokio::test]
    async fn hot_swap_to_openai_keeps_view_image() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory_with_builtins(&temp), 10);
        runtime.set_default_llm_client(Some(Arc::new(MockLlmClient)));

        // Create session with an Anthropic model (supports image_tool_results).
        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .unwrap();
        let (event_tx, _event_rx) = mpsc::channel(100);

        // Materialize the session with the first turn.
        let _ = runtime
            .start_turn(
                &session_id,
                "Hello".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        // Hot-swap to an OpenAI Responses model (supports image_tool_results).
        let overrides = crate::handlers::turn::TurnOverrides {
            model: Some("gpt-5.4".to_string()),
            provider: Some("openai".to_string()),
            ..Default::default()
        };
        let (event_tx2, _event_rx2) = mpsc::channel(100);
        let _ = runtime
            .start_turn(
                &session_id,
                "Second turn".into(),
                event_tx2,
                None,
                None,
                None,
                Some(overrides),
            )
            .await
            .unwrap();

        let info = runtime
            .read_session_rich(&session_id)
            .await
            .unwrap()
            .expect("hot-swapped session should be readable");
        let capabilities = info
            .resolved_capabilities
            .expect("hot-swapped session should expose resolved capabilities");
        assert_eq!(info.model, "gpt-5.4");
        assert_eq!(info.provider, "openai");
        assert!(capabilities.vision);
        assert!(capabilities.image_input);
        assert!(
            capabilities.image_tool_results,
            "OpenAI hot-swap should update resolved image tool-result support"
        );
        assert!(capabilities.web_search);
        assert!(capabilities.image_generation);

        // Export the session and check that the capability-owned visibility
        // state keeps view_image available without mutating the external overlay.
        let session = runtime
            .service
            .export_live_session(&session_id)
            .await
            .unwrap();
        let visibility_state = exported_tool_visibility_state(&session);
        assert_eq!(
            visibility_state.capability_base_filter,
            meerkat_core::ToolFilter::All,
            "hot-swap to OpenAI Responses should keep view_image available"
        );
        assert_eq!(
            visibility_state.staged_filter,
            meerkat_core::ToolFilter::All,
            "hot-swap should not widen or replace the user-owned external filter"
        );
    }

